// 重构前：面条式代码，用 if-else 处理不同形状的面积计算
// 要求：重构成 OOP（Shape 基类 + Circle/Rectangle/Triangle 子类）

export type ShapeType = 'circle' | 'rectangle' | 'triangle'

// 计算面积（面条式，要求重构）
export function calculateArea(type: ShapeType, ...args: number[]): number {
  if (type === 'circle') {
    const radius = args[0] || 0
    return Math.PI * radius * radius
  } else if (type === 'rectangle') {
    const width = args[0] || 0
    const height = args[1] || 0
    return width * height
  } else if (type === 'triangle') {
    const base = args[0] || 0
    const height = args[1] || 0
    return 0.5 * base * height
  }
  return 0
}
